/**
 * Runtime support for vecDSL programs generated for PostgreSQL with pgvector, through node-postgres (pg). Generated by
 * vecDSL 7. Do not edit.
 *
 * Every statement arrives as SQL text with numbered parameters ($1, $2, ...), identical in the Python, TypeScript and Java
 * programs. Parameters are sent as text (lists and objects as JSON text) and cast in the SQL; queries return one json value
 * per row. Each call runs in its own transaction (BEGIN ... COMMIT), so SET LOCAL settings never outlive the statement.
 */
import { readFileSync } from "node:fs";
import pg from "pg";

const DIGITS = 6;
const BATCH = 500;
const ISOLATION: Record<string, string> = {
  read_uncommitted: "READ UNCOMMITTED",
  read_committed: "READ COMMITTED",
  repeatable_read: "REPEATABLE READ",
  serializable: "SERIALIZABLE",
};

export class UnsupportedFeature extends Error {}

export function unsupported(vendor: string, feature: string): never {
  throw new UnsupportedFeature(`${feature} is not supported for target ${vendor}`);
}

export function env(name: string): string {
  const value = process.env[name];
  if (value === undefined) {
    throw new Error(`environment variable ${name} is not set`);
  }
  return value;
}

export interface Step {
  sql: string;
  params?: unknown[];
}

/** The server endpoint and one connection per database the program uses; the password comes from the environment. */
export class Client {
  readonly host: string;
  readonly port: number;
  readonly user: string;
  readonly database: string;
  readonly ssl: boolean;
  readonly connectTimeoutMillis: number;
  private readonly password: string | undefined;
  private readonly connections = new Map<string, pg.Client>();

  constructor(url: string, passwordVariable: string) {
    const parsed = new URL(url);
    if (parsed.protocol !== "postgresql:" && parsed.protocol !== "postgres:") {
      throw new Error(`expected a postgresql:// URI, got ${url}`);
    }
    if (parsed.password !== "") {
      throw new Error("the connection URI must not contain a password; set it in the environment");
    }
    this.host = parsed.hostname || "127.0.0.1";
    this.port = parsed.port ? Number(parsed.port) : 5432;
    this.user = decodeURIComponent(parsed.username || "postgres");
    this.database = decodeURIComponent(parsed.pathname.replace(/^\//, "")) || this.user;
    this.ssl = ["require", "verify-ca", "verify-full"].includes(parsed.searchParams.get("sslmode") ?? "");
    this.connectTimeoutMillis = 1000 * Number(parsed.searchParams.get("connect_timeout") ?? "10");
    this.password = process.env[passwordVariable];
  }

  async connection(database?: string): Promise<pg.Client> {
    const name = database ?? this.database;
    let connection = this.connections.get(name);
    if (connection === undefined) {
      connection = new pg.Client({ host: this.host, port: this.port, user: this.user, password: this.password, database: name, ssl: this.ssl,
        connectionTimeoutMillis: this.connectTimeoutMillis });
      await connection.connect();
      await connection.query("CREATE EXTENSION IF NOT EXISTS vector");
      this.connections.set(name, connection);
    }
    return connection;
  }

  async forget(database: string): Promise<void> {
    const connection = this.connections.get(database);
    if (connection !== undefined) {
      this.connections.delete(database);
      await connection.end();
    }
  }

  async close(): Promise<void> {
    for (const connection of this.connections.values()) {
      await connection.end();
    }
    this.connections.clear();
  }
}

export async function connect(options: { url: string; passwordVariable?: string }): Promise<Client> {
  return new Client(options.url, options.passwordVariable ?? "VECDSL_PGVECTOR_PASSWORD");
}

/** A parameter as text: strings as they are, booleans and numbers in JSON form, lists and objects as JSON. */
function text(value: unknown): string | null {
  if (value === null || value === undefined) {
    return null;
  }
  return typeof value === "string" ? value : JSON.stringify(value);
}

/** Result values in one form for every host language: floats rounded to six decimals. */
function normalize(value: unknown): unknown {
  if (typeof value === "number") {
    return Number.isInteger(value) ? value : Number(value.toFixed(DIGITS));
  }
  if (Array.isArray(value)) {
    return value.map(normalize);
  }
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(Object.entries(value as Record<string, unknown>).map(([key, item]) => [key, normalize(item)]));
  }
  return value;
}

async function run(connection: pg.Client, sql: string, params: unknown[] = []): Promise<unknown[]> {
  const result = await connection.query({ text: sql, values: params.map(text) });
  if (result.fields === undefined || result.fields.length === 0) {
    return [];
  }
  const column = result.fields[0].name;
  return result.rows.map((row: Record<string, unknown>) => normalize(row[column]));
}

async function inTransaction(
  client: Client,
  steps: Step[],
  database: string | undefined,
  isolation?: string,
  settings?: Record<string, string>,
): Promise<unknown[][]> {
  const connection = await client.connection(database);
  await connection.query("BEGIN" + (isolation ? ` ISOLATION LEVEL ${ISOLATION[isolation]}` : ""));
  try {
    for (const [name, setting] of Object.entries(settings ?? {})) {
      await connection.query("SELECT set_config($1, $2, true)", [name, setting]);
    }
    const results: unknown[][] = [];
    for (const step of steps) {
      results.push(await run(connection, step.sql, step.params));
    }
    await connection.query("COMMIT");
    return results;
  } catch (error) {
    await connection.query("ROLLBACK");
    throw error;
  }
}

/** The json values of a query's rows. */
export async function query(
  client: Client,
  args: { sql: string; params?: unknown[]; settings?: Record<string, string>; database?: string },
): Promise<unknown[]> {
  return (await inTransaction(client, [{ sql: args.sql, params: args.params }], args.database, undefined, args.settings))[0];
}

/** The json value of the first row, or null. */
export async function value(
  client: Client,
  args: { sql: string; params?: unknown[]; settings?: Record<string, string>; database?: string },
): Promise<unknown> {
  const rows = await query(client, args);
  return rows.length > 0 ? rows[0] : null;
}

export async function exists(client: Client, args: { sql: string; params?: unknown[]; database?: string }): Promise<boolean> {
  return Boolean(await value(client, args));
}

/** Statements without results (DDL) in one transaction. */
export async function execute(client: Client, args: { steps: Step[]; database?: string }): Promise<void> {
  await inTransaction(client, args.steps, args.database);
}

/** The statements of a vecDSL transaction in one PostgreSQL transaction; any failure rolls back all of them. */
export async function transaction(
  client: Client,
  args: { steps: Step[]; isolation?: string; database?: string },
): Promise<unknown[]> {
  return (await inTransaction(client, args.steps, args.database, args.isolation)).map((rows) => (rows.length > 0 ? rows[0] : null));
}

/** A statement that cannot run inside a transaction block (CREATE DATABASE, VACUUM, CREATE INDEX CONCURRENTLY). */
export async function autocommit(client: Client, args: { sql: string; database?: string; closes?: string }): Promise<void> {
  if (args.closes !== undefined) {
    await client.forget(args.closes);
  }
  await (await client.connection(args.database)).query(args.sql);
}

/** Records of a local JSON array or JSON Lines file (file:// URI or path). */
export async function readRecords(_client: Client, args: { location: string }): Promise<Record<string, unknown>[]> {
  const path = args.location.startsWith("file://") ? args.location.slice("file://".length) : args.location;
  const content = readFileSync(path, "utf8");
  if (content.trimStart().startsWith("[")) {
    return JSON.parse(content) as Record<string, unknown>[];
  }
  return content
    .split(/\r?\n/)
    .filter((line) => line.trim() !== "")
    .map((line) => JSON.parse(line) as Record<string, unknown>);
}

/** A local file written in batches by one INSERT statement ($1 is the batch), all in one transaction. */
export async function importFile(
  client: Client,
  args: { sql: string; location: string; params?: unknown[]; batch_size?: number; database?: string },
): Promise<Record<string, number>> {
  const records = await readRecords(client, { location: args.location });
  const size = args.batch_size ?? BATCH;
  const steps: Step[] = [];
  for (let start = 0; start < records.length; start += size) {
    steps.push({ sql: args.sql, params: [records.slice(start, start + size), ...(args.params ?? [])] });
  }
  const totals: Record<string, number> = {};
  for (const rows of await inTransaction(client, steps, args.database)) {
    const counts = (rows[0] ?? {}) as Record<string, number>;
    for (const [key, count] of Object.entries(counts)) {
      totals[key] = (totals[key] ?? 0) + count;
    }
  }
  return totals;
}
